using System.Windows; using ANLAbel.App.ViewModels;
namespace ANLAbel.App;
public partial class DocumentLibraryWindow : Window { private readonly DocumentLibraryViewModel _vm; private readonly Func<string,Task> _open; private readonly Action _revisions; public DocumentLibraryWindow(Func<string> root, Func<string,Task> open, Action revisions) { InitializeComponent(); _vm=new DocumentLibraryViewModel(root); _open=open; _revisions=revisions; DataContext=_vm; } private async void Window_Loaded(object s,RoutedEventArgs e){Loaded-=Window_Loaded;await _vm.RefreshAsync();} private async void Refresh_Click(object s,RoutedEventArgs e)=>await _vm.RefreshAsync(); private async void Open_Click(object s,RoutedEventArgs e){if(_vm.SelectedItem is not null) await _open(_vm.SelectedItem.FullPath);} private void Revision_Click(object s,RoutedEventArgs e)=>_revisions(); private void Close_Click(object s,RoutedEventArgs e)=>Close(); }
